import json
inv = json.load(open('bench/results/2026-10-12/m1-ngram/recon/inventory.json'))
runs = inv['runs']
# find a mem0 run
for r in runs:
    if 'mem0' in r['run_id']:
        print('MEM0 run:', r['run_id'])
        print('mem0_dbs:', r.get('mem0_dbs'))
        # show a step with mem taps
        for sk, sp in r['steps'].items():
            te = [t for t in sp['tap_records'] if t.get('role')=='mem']
            if te:
                print('  step', sk, 'n mem taps =', len(te))
                print('  first mem tap:', json.dumps(te[0], default=str))
        break
# also show a baseline agent tap with cache
for r in runs:
    if 'baseline' in r['run_id']:
        for sk, sp in r['steps'].items():
            at = [t for t in sp['tap_records'] if t.get('role')=='agent']
            if at:
                print()
                print('BASELINE run:', r['run_id'], 'step', sk)
                for t in at:
                    print('  agent:', t)
                break
        break
"

